"""Prompts, copied verbatim from the n8n workflows they replaced so model
output is unchanged by the move to Python.

`prompts/*.md` are the longer design templates from initial planning; the
live system prompts were always the shorter ones below. Image Gen is the
exception — it loads prompts/image-gen-draft.md directly.
"""

from pathlib import Path

PROMPTS_DIR = Path(__file__).resolve().parents[2] / "prompts"


def load_section(name: str, section: str = "System") -> str:
    """Return the text under `## <section>` in prompts/<name>.md."""
    text = (PROMPTS_DIR / f"{name}.md").read_text(encoding="utf-8")
    body = text.split(f"## {section}\n", 1)[1]
    return body.split("\n## ", 1)[0].strip()


